=== FIX 1: /luxon/src/interval.js, method `static fromISO(text, opts)` ===
Replace the entire body of `static fromISO(text, opts)` (currently the method that splits on '/' and calls DateTime.fromISO on both halves) with EXACTLY this:

  static fromISO(text, opts) {
    const [s, e] = (text || "").split("/", 2);
    if (s && e) {
      let start, startIsValid;
      try {
        start = DateTime.fromISO(s, opts);
        startIsValid = start.isValid;
      } catch (e) {
        startIsValid = false;
      }

      let end, endIsValid;
      try {
        end = DateTime.fromISO(e, opts);
        endIsValid = end.isValid;
      } catch (e) {
        endIsValid = false;
      }

      if (startIsValid && endIsValid) {
        return Interval.fromDateTimes(start, end);
      }

      if (startIsValid) {
        const dur = Duration.fromISO(e, opts);
        if (dur.isValid) {
          return Interval.after(start, dur);
        }
      } else if (endIsValid) {
        const dur = Duration.fromISO(s, opts);
        if (dur.isValid) {
          return Interval.before(end, dur);
        }
      }
    }
    return Interval.invalid("unparsable", `the input "${text}" can't be parsed asISO 8601`);
  }

Reason: when Settings.throwOnInvalid is true, DateTime.fromISO throws on the duration half of '<start>/<duration>'; catching it lets the duration branch run.

=== FIX 2: /luxon/src/impl/util.js, function `objToLocalTS` ===
Replace the whole `objToLocalTS` function with EXACTLY this:

export function objToLocalTS(obj) {
  const year = obj.year < 100 && obj.year >= 0 ? obj.year + 400 : obj.year;
  let d = Date.UTC(
    year,
    obj.month - 1,
    obj.day,
    obj.hour,
    obj.minute,
    obj.second,
    obj.millisecond
  );

  // for legacy reasons, years between 0 and 99 are interpreted as 19XX; revert that
  if (obj.year < 100 && obj.year >= 0) {
    d = new Date(d);
    d.setUTCFullYear(d.getUTCFullYear() - 400);
  }
  return +d;
}

Reason: Date.UTC maps years 0-99 to 1900-1999, and any day/month overflow is resolved with the wrong leap-year rules. Shifting by 400 years (the Gregorian repeat period) keeps leap-year rules identical while avoiding the 0-99 remap.

=== FIX 3: /luxon/src/datetime.js, getter `get isInDST()` ===
Replace the whole `get isInDST()` getter with EXACTLY this:

  get isInDST() {
    if (this.isOffsetFixed) {
      return false;
    } else {
      let minOffset = this.offset;
      for (let m = 1; m <= 12; m++) {
        minOffset = Math.min(minOffset, this.set({ month: m }).offset);
      }
      return this.offset > minOffset;
    }
  }

Reason: the old heuristic compared against January and May, which fails when January is already in DST (e.g. US 1974). Comparing against the minimum offset over the year (the standard offset) is correct.

